+std::vector<uint16_t> OriginalTopology(bool cube,std::initializer_list<unsigned> corners)
+{
+ std::vector<uint16_t> out;
+ if(cube)for(unsigned face=0;face<6;++face)for(unsigned c:corners)out.push_back(face*4+c);
+ else for(unsigned i=0;i<24;++i)out.push_back(i);
+ for(unsigned c:corners)out.push_back(24+c);
+ return out;
+}
+auto Indices(const std::vector<uint16_t>& values,unsigned width)
+{
+ const auto type=width==2?NativeScalarType::UInt16:NativeScalarType::UInt32;
+ auto b=Buffer(NativeBufferKind::Index,values.size(),width,{Attr(0,0,1,type)});
+ for(size_t i=0;i<values.size();++i){if(width==2)Put(b->bytes,i*width,values[i]);else Put(b->bytes,i*width,uint32_t(values[i]));}
+ return b;
+}
